commit 79d8c948e6aaec343e6f07d9bab9f7edcf1fa368
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Thu Jan 21 16:42:34 2021 +0000

    Fix some fuzz issues in CRAM 3.1.

    Credit to OSS-Fuzz

    - Check for return value from RANS4x16 and ARITH codecs so a valid
      stream that is the wrong size still frees up the memory.
      Fixes oss-fuzz 29786
      Fixes oss-fuzz 29787
      Fixes oss-fuzz 29796

    - Check for return value from TOK3 codec so error is bubbled up
      Fixes oss-fuzz 29789

diff --git a/cram/cram_io.c b/cram/cram_io.c
index 4f95f940..30f109d6 100644
--- a/cram/cram_io.c
+++ b/cram/cram_io.c
@@ -1680,8 +1680,12 @@ int cram_uncompress_block(cram_block *b) {
     case RANS_PR0: {
         unsigned int usize = b->uncomp_size, usize2;
         uncomp = (char *)rans_uncompress_4x16(b->data, b->comp_size, &usize2);
-        if (!uncomp || usize != usize2)
+        if (!uncomp)
+            return -1;
+        if (usize != usize2) {
+            free(uncomp);
             return -1;
+        }
         b->orig_method = RANS_PR0 + (b->data[0]&1)
             + 2*((b->data[0]&0x40)>0) + 4*((b->data[0]&0x80)>0);
         free(b->data);
@@ -1696,8 +1700,12 @@ int cram_uncompress_block(cram_block *b) {
     case ARITH_PR0: {
         unsigned int usize = b->uncomp_size, usize2;
         uncomp = (char *)arith_uncompress_to(b->data, b->comp_size, NULL, &usize2);
-        if (!uncomp || usize != usize2)
+        if (!uncomp)
             return -1;
+        if (usize != usize2) {
+            free(uncomp);
+            return -1;
+        }
         b->orig_method = ARITH_PR0 + (b->data[0]&1)
             + 2*((b->data[0]&0x40)>0) + 4*((b->data[0]&0x80)>0);
         free(b->data);
@@ -1712,6 +1720,8 @@ int cram_uncompress_block(cram_block *b) {
     case TOK3: {
         uint32_t out_len;
         uint8_t *cp = decode_names(b->data, b->comp_size, &out_len);
+        if (!cp)
+            return -1;
         b->orig_method = TOK3;
         b->method = RAW;
         free(b->data);
